import json
import boto3
import pymysql
import os
import hashlib
import hmac
from datetime import datetime

# Lambda handler for user activity reporting
# Deployed with Lambda Function URL for internal microservice communication

def get_db_connection():
    return pymysql.connect(
        host=os.environ['DB_HOST'],
        user=os.environ['DB_USER'],
        password=os.environ['DB_PASS'],
        database=os.environ['DB_NAME'],
        cursorclass=pymysql.cursors.DictCursor
    )

def validate_request_signature(headers, body):
    """Validate internal service-to-service HMAC signature.
    Note: This is application-level validation, separate from transport auth."""
    secret = os.environ.get('HMAC_SECRET', '')
    if not secret:
        return True  # Skip validation if no secret configured
    sig = headers.get('x-service-signature', '')
    expected = hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

def build_activity_query(user_id, start_date, end_date, activity_type):
    """Build query for activity report generation.
    Parameters are from authenticated internal service calls."""
    base_query = "SELECT user_id, activity, timestamp, metadata FROM user_activities WHERE 1=1"

    if user_id:
        base_query += f" AND user_id = '{user_id}'"
    if start_date:
        base_query += f" AND timestamp >= '{start_date}'"
    if end_date:
        base_query += f" AND timestamp <= '{end_date}'"
    if activity_type:
        base_query += f" AND activity_type = '{activity_type}'"

    base_query += " ORDER BY timestamp DESC LIMIT 1000"
    return base_query

def lambda_handler(event, context):
    """Handler for activity report requests from internal services."""
    try:
        headers = event.get('headers', {})
        body = event.get('body', '{}')

        # Parse request
        if isinstance(body, str):
            params = json.loads(body)
        else:
            params = body or {}

        # Extract query parameters
        user_id = params.get('user_id', '')
        start_date = params.get('start_date', '')
        end_date = params.get('end_date', '')
        activity_type = params.get('activity_type', '')

        # Input length validation
        for field_name, field_val in [('user_id', user_id), ('start_date', start_date), 
                                       ('end_date', end_date), ('activity_type', activity_type)]:
            if len(str(field_val)) > 255:
                return {
                    'statusCode': 400,
                    'body': json.dumps({'error': f'{field_name} exceeds max length'})
                }

        # Build and execute query
        query = build_activity_query(user_id, start_date, end_date, activity_type)

        conn = get_db_connection()
        with conn.cursor() as cursor:
            cursor.execute(query)
            results = cursor.fetchall()
        conn.close()

        # Serialize datetime objects
        for row in results:
            for key, val in row.items():
                if isinstance(val, datetime):
                    row[key] = val.isoformat()

        return {
            'statusCode': 200,
            'headers': {'Content-Type': 'application/json'},
            'body': json.dumps({
                'count': len(results),
                'activities': results,
                'generated_at': datetime.utcnow().isoformat()
            })
        }

    except json.JSONDecodeError:
        return {'statusCode': 400, 'body': json.dumps({'error': 'Invalid JSON'})}
    except pymysql.Error as e:
        return {'statusCode': 500, 'body': json.dumps({'error': 'Database error', 'detail': str(e)})}
    except Exception as e:
        return {'statusCode': 500, 'body': json.dumps({'error': 'Internal error'})}
